 "content": "def transform(grid):
    """Restore cells marked 2 from the grid's dihedral symmetry."""
    n = len(grid)
    out = [row[:] for row in grid]
    def orbit(r, c):
        return {(r, c), (c, r), (n-1-r, n-1-c), (n-1-c, n-1-r),
                (r, n-1-c), (n-1-r, c), (c, n-1-r), (n-1-c, r)}
    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] == 2:
                vals = [grid[rr][cc] for rr, cc in orbit(r, c) if grid[rr][cc] != 2]
                if vals:
                    out[r][c] = vals[0]
